function canMemberReserve(memberId: string, loans: Loan[], now: Date): LendingResult<boolean> {
  const flagged: Loan[] = flagOverdueLoans(loans, now);
  const blocking: Loan[] = [];
  for (let i = 0; i < flagged.length; i++) {
    const loan: Loan = flagged[i];
    if (loan.memberId === memberId && loan.status === 'Overdue') {
      blocking.push(loan);
    }
  }
  if (blocking.length > 0) {
    const ids: string[] = [];
    for (let i = 0; i < blocking.length; i++) {
      ids.push(blocking[i].id);
    }
    return {
      ok: false,
      reason: 'Member has overdue loan(s) and cannot reserve another tool.',
      blockingLoanIds: ids
    };
  }
  return { ok: true, value: true };
}

/**
 * Flag every loan whose due instant is strictly before `now` and which has no
 * returned timestamp as Overdue. A loan exactly at its due instant is not yet
 * overdue. Returned loans are never re-flagged.
 * @param loans - the loan set to evaluate
 * @param now - the reference instant
 * @returns a new loan array with overdue loans marked status 'Overdue'
 */
// req-3
function flagOverdueLoans(loans: Loan[], now: Date): Loan[] {
  const flagged: Loan[] = [];
  for (let i = 0; i < loans.length; i++) {
    const loan: Loan = loans[i];
    const dueMs: number = loan.dueAt.getTime();
    const nowMs: number = now.getTime();
    if (loan.returnedAt === null && dueMs < nowMs) {
      flagged.push({
        id: loan.id,
        toolId: loan.toolId,
        memberId: loan.memberId,
        checkedOutAt: loan.checkedOutAt,
        dueAt: loan.dueAt,
        returnedAt: loan.returnedAt,
        status: 'Overdue',
        damageReport: loan.damageReport
      });
    } else {
      flagged.push({
        id: loan.id,
        toolId: loan.toolId,
        memberId: loan.memberId,
        checkedOutAt: loan.checkedOutAt,
        dueAt: loan.dueAt,
        returnedAt: loan.returnedAt,
        status: loan.status,
        damageReport: loan.damageReport
