  const flagged: Loan[] = flagOverdueLoans(loans, now);
  const overdue: Loan[] = [];
  for (let i = 0; i < flagged.length; i++) {
    if (flagged[i].status === 'Overdue') {
      overdue.push(flagged[i]);
